// P7 west kitchen (box x86..87, y3..6, z14..15): the hearth is in the back wall (mouth 87,3,16, fire outside), a lit
// furnace stove stands in front of it, a one-cell spruce table sits by the west wall under a standing lantern, and a
// hanging lantern lights the room from the ceiling. Cells (86,3,14) and (87,3,14) stay clear: the lane from the door
// (86,3,13) to the stove.
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { stove, hanging_lantern } from "../vocab.mjs";

export function build(g) {
  stove(g, 87, 3, 15, "north");                 // focal piece: lit furnace in front of the hearth, front to the room
  g.set(86, 3, 15, "spruce_fence");             // table leg
  g.set(86, 4, 15, ...B.slab("spruce", "top")); // table top
  g.set(86, 5, 15, ...B.lantern(false));        // standing lantern on the table top
  hanging_lantern(g, 86, 6, 14);                // ceiling light over the lane from the door
}

